class Solution {
    public int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        if (rows < 3 || cols < 3) {
            return 0;
        }
        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) -> a[2] - b[2]);
        boolean[][] visited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            addBoundaryCell(r, 0, heightMap, visited, heap);
            addBoundaryCell(r, cols - 1, heightMap, visited, heap);
        }
        for (int c = 1; c < cols - 1; c++) {
            addBoundaryCell(0, c, heightMap, visited, heap);
            addBoundaryCell(rows - 1, c, heightMap, visited, heap);
        }

        int trapped = 0;
        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            for (int[] direction : directions) {
                int nr = cell[0] + direction[0];
                int nc = cell[1] + direction[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) {
                    continue;
                }
                visited[nr][nc] = true;
                trapped += Math.max(0, cell[2] - heightMap[nr][nc]);
                heap.offer(new int[] {nr, nc, Math.max(cell[2], heightMap[nr][nc])});
            }
        }
        return trapped;
    }

    private void addBoundaryCell(int r, int c, int[][] heightMap, boolean[][] visited,
                                 java.util.PriorityQueue<int[]> heap) {
        if (visited[r][c]) {
            return;
        }
        visited[r][c] = true;
        heap.offer(new int[] {r, c, heightMap[r][c]});
    }
}

class Solution {
    public int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        if (rows < 3 || cols < 3) {
            return 0;
        }
        int[][] level = new int[rows][cols];
        for (int[] row : level) {
            java.util.Arrays.fill(row, Integer.MAX_VALUE);
        }
        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) -> a[2] - b[2]);
        for (int r = 0; r < rows; r++) {
            offerLevel(r, 0, heightMap[r][0], level, heap);
            offerLevel(r, cols - 1, heightMap[r][cols - 1], level, heap);
        }
        for (int c = 1; c < cols - 1; c++) {
            offerLevel(0, c, heightMap[0][c], level, heap);
            offerLevel(rows - 1, c, heightMap[rows - 1][c], level, heap);
        }

        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            int r = cell[0];
            int c = cell[1];
            int waterLevel = cell[2];
            if (waterLevel != level[r][c]) {
                continue;
            }
            for (int[] direction : directions) {
                int nr = r + direction[0];
                int nc = c + direction[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int nextLevel = Math.max(waterLevel, heightMap[nr][nc]);
                if (nextLevel < level[nr][nc]) {
                    level[nr][nc] = nextLevel;
                    heap.offer(new int[] {nr, nc, nextLevel});
                }
            }
        }

        int trapped = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                trapped += level[r][c] - heightMap[r][c];
            }
        }
        return trapped;
    }

    private void offerLevel(int r, int c, int value, int[][] level,
                            java.util.PriorityQueue<int[]> heap) {
        if (value < level[r][c]) {
            level[r][c] = value;
            heap.offer(new int[] {r, c, value});
        }
    }
}

class Solution {
    public int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        if (rows < 3 || cols < 3) {
            return 0;
        }
        int maxHeight = 0;
        for (int[] row : heightMap) {
            for (int height : row) {
                maxHeight = Math.max(maxHeight, height);
            }
        }
        int[][] level = new int[rows][cols];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isBoundary(r, c, rows, cols)) {
                    level[r][c] = heightMap[r][c];
                    queue.addLast(new int[] {r, c});
                } else {
                    level[r][c] = maxHeight;
                }
            }
        }

        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!queue.isEmpty()) {
            int[] cell = queue.removeFirst();
            for (int[] direction : directions) {
                int nr = cell[0] + direction[0];
                int nc = cell[1] + direction[1];
                if (nr <= 0 || nr >= rows - 1 || nc <= 0 || nc >= cols - 1) {
                    continue;
                }
                int candidate = Math.max(heightMap[nr][nc], level[cell[0]][cell[1]]);
                if (candidate < level[nr][nc]) {
                    level[nr][nc] = candidate;
                    queue.addLast(new int[] {nr, nc});
                }
            }
        }

        int trapped = 0;
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                trapped += level[r][c] - heightMap[r][c];
            }
        }
        return trapped;
    }

    private boolean isBoundary(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }
}

class Solution {
    public int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        if (rows < 3 || cols < 3) {
            return 0;
        }
        int totalCells = rows * cols;
        Integer[] order = new Integer[totalCells];
        for (int id = 0; id < totalCells; id++) {
            order[id] = id;
        }
        java.util.Arrays.sort(order, (a, b) -> Integer.compare(
                heightMap[a / cols][a % cols], heightMap[b / cols][b % cols]));

        UnionFind unionFind = new UnionFind(totalCells);
        boolean[] active = new boolean[totalCells];
        int[] level = new int[totalCells];
        java.util.Arrays.fill(level, -1);
        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int id : order) {
            int r = id / cols;
            int c = id % cols;
            int height = heightMap[r][c];
            active[id] = true;
            unionFind.activate(id, isBoundary(r, c, rows, cols));
            int root = unionFind.find(id);
            for (int[] direction : directions) {
                int nr = r + direction[0];
                int nc = c + direction[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int nextId = nr * cols + nc;
                if (active[nextId]) {
                    root = unionFind.union(root, nextId);
                }
            }
            if (unionFind.borderConnected[root]) {
                unionFind.assignLevel(root, height, level);
            }
        }

        int trapped = 0;
        for (int id = 0; id < totalCells; id++) {
            trapped += level[id] - heightMap[id / cols][id % cols];
        }
        return trapped;
    }

    private boolean isBoundary(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] size;
        private final boolean[] borderConnected;
        private final java.util.ArrayList<Integer>[] unresolved;

        @SuppressWarnings("unchecked")
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            borderConnected = new boolean[n];
            unresolved = (java.util.ArrayList<Integer>[]) new java.util.ArrayList[n];
            java.util.Arrays.fill(parent, -1);
        }

        void activate(int id, boolean touchesBorder) {
            parent[id] = id;
            size[id] = 1;
            borderConnected[id] = touchesBorder;
            unresolved[id] = new java.util.ArrayList<>();
            unresolved[id].add(id);
        }

        int find(int id) {
            if (parent[id] != id) {
                parent[id] = find(parent[id]);
            }
            return parent[id];
        }

        int union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return rootA;
            }
            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
            borderConnected[rootA] = borderConnected[rootA] || borderConnected[rootB];
            unresolved[rootA].addAll(unresolved[rootB]);
            unresolved[rootB].clear();
            return rootA;
        }

        void assignLevel(int root, int waterLevel, int[] level) {
            root = find(root);
            for (int id : unresolved[root]) {
                level[id] = waterLevel;
            }
            unresolved[root].clear();
        }
    }
}

class Solution {
    public int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        if (rows < 3 || cols < 3) {
            return 0;
        }
        int maxHeight = 0;
        for (int[] row : heightMap) {
            for (int height : row) {
                maxHeight = Math.max(maxHeight, height);
            }
        }
        int trapped = 0;
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                int low = heightMap[r][c];
                int high = maxHeight;
                while (low < high) {
                    int mid = low + (high - low) / 2;
                    if (canEscapeAtLevel(heightMap, r, c, mid)) {
                        high = mid;
                    } else {
                        low = mid + 1;
                    }
                }
                trapped += low - heightMap[r][c];
            }
        }
        return trapped;
    }

    private boolean canEscapeAtLevel(int[][] heightMap, int startR, int startC, int level) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        boolean[][] seen = new boolean[rows][cols];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        queue.addLast(new int[] {startR, startC});
        seen[startR][startC] = true;
        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!queue.isEmpty()) {
            int[] cell = queue.removeFirst();
            if (cell[0] == 0 || cell[0] == rows - 1 || cell[1] == 0 || cell[1] == cols - 1) {
                return true;
            }
            for (int[] direction : directions) {
                int nr = cell[0] + direction[0];
                int nc = cell[1] + direction[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || seen[nr][nc]) {
                    continue;
                }
                if (heightMap[nr][nc] <= level) {
                    seen[nr][nc] = true;
                    queue.addLast(new int[] {nr, nc});
                }
            }
        }
        return false;
    }
}
